const $=s=>document.querySelector(s),app=$('#app');
const paths={pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',chat:'<path d="M3 4h18v14H8l-5 4Z"/>',search:'<circle cx="10" cy="10" r="8"/><path d="m16 16 6 6"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M7 10V6a5 5 0 0 1 10 0v4"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 19h4"/>'};
const icon=n=>`<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.chat}</svg></span>`;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,d=[]){try{return JSON.parse(localStorage.getItem('qure-'+k))??d}catch{return d}}
function save(k,v){try{localStorage.setItem('qure-'+k,JSON.stringify(v))}catch{toast('Browser storage is unavailable. Your changes will not persist.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function nav(route){return `<nav aria-label="Main navigation">${[['home','Home'],['medimap','MediMap'],['chatbot','ChatBot'],['symptoms','Symptoms'],['api-portal','API']].map(([r,t])=>`<a class="${r===route?'active':''}" href="#/${r}">${t}</a>`).join('')}</nav>`}
const tools=[['pin','MediMap','Find hospitals and medical facilities near you with an interactive map. Get directions and contact information instantly.','medimap'],['chat','AI Health Assistant','Your 24/7 intelligent health companion providing personalized advice, answering questions, and guiding your wellness journey.','chatbot'],['search','Symptom Intelligence','Advanced symptom analysis with AI-powered insights, likelihood assessments, and guidance on when to seek medical care.','symptoms']];
function home(){app.innerHTML=`<header class="hero"><div class="ribbon"></div><div class="ribbon two"></div><div class="ribbon three"></div><nav><a href="#about">About</a><a href="#info">Info</a><a href="#tools">Tools</a></nav><div class="hero-content"><h1>Welcome to <em>Qure</em></h1><p class="tagline">"Healthcare made efficient"</p><a href="#tools" class="down" aria-label="Explore tools">⌄</a></div></header><section class="section privacy" id="about"><h2>Your Health, Reimagined</h2><p class="lead" style="margin-bottom:0">Qure is your intelligent health companion powered by advanced AI. Get personalized insights, find nearby hospitals, track symptoms, and make informed health decisions — all in one place, all on your device.</p></section><section class="section" id="tools"><h2>Powerful Health Tools</h2><p class="lead">A focused suite of tools designed to help you manage your health with precision and confidence.</p><div class="cards">${tools.map(([i,t,d,r])=>`<article class="card">${icon(i)}<h3>${t}</h3><p>${d}</p><a class="explore" href="#/${r}">Explore &nbsp;→</a></article>`).join('')}</div></section><section class="section privacy" id="info"><h2>Your Data, Your Control</h2><p class="lead">Built with privacy-first principles. Your health data stays on your device with advanced local storage and optional cloud sync.</p><div class="privacy-grid"><div>${[['database','Local Storage','All your health data is stored locally using localStorage for maximum privacy and offline access.'],['lock','Privacy First','Your personal health information never leaves your device unless you explicitly choose to share it.'],['phone','Offline Ready','Access your health data anytime, anywhere. Works completely offline with smart sync when online.']].map(([i,t,d])=>`<div class="feature">${icon(i)}<div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div><div class="card intel"><h3>Advanced AI Health Intelligence</h3><ul><li>♧ &nbsp;Sarvam AI Integration</li><li>⌕ &nbsp;Nearby Facilities</li><li>♧ &nbsp;Hospital Finder</li><li>▱ &nbsp;Personalized Insights</li><li>ϟ &nbsp;Symptom Analysis</li><li>♡ &nbsp;Health Tracking</li></ul><a class="green" href="#/chatbot">Start Your Health Journey &nbsp; →</a></div></div></section><footer>Qure · Healthcare made efficient</footer>`;
// Preserve the supplied homepage copy; describe actual connectivity requirements separately.
}
let map,markers,searchController,searchGeneration=0;let center=[28.66,77.09];let mapTimer;
function medimap(){app.innerHTML=nav('medimap')+`<main class="container"><h1>MediMap</h1><p class="subtitle">Find hospitals and medical facilities near you</p><div class="panel toolbar"><label for="radius">Search radius:</label><input id="radius" type="range" min="1" max="20" value="5"><output id="radius-value">5km</output><button id="recenter" class="green">➤ Re-centre</button></div><div class="map-layout"><div><div id="map"></div><p class="note" id="map-note">Showing Delhi by default. Use Re-centre to search near your location. Map and hospital search require internet.</p></div><aside><h3>Nearby Hospitals</h3><div id="hospitals" aria-live="polite">Finding hospitals…</div></aside></div></main>`;
if(!window.L){$('#map').textContent='Map could not load. Check your internet connection and reload.';$('#hospitals').textContent='Map service unavailable.';return}map=L.map('map').setView(center,13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);markers=L.layerGroup().addTo(map);$('#radius').oninput=e=>{$('#radius-value').textContent=e.target.value+'km';clearTimeout(mapTimer);mapTimer=setTimeout(findHospitals,450)};$('#recenter').onclick=()=>{if(!navigator.geolocation)return toast('Location is not supported by this browser.');$('#map-note').textContent='Requesting your location…';navigator.geolocation.getCurrentPosition(p=>{center=[p.coords.latitude,p.coords.longitude];map.setView(center,13);$('#map-note').textContent='Showing facilities near your location.';findHospitals()},()=>{$('#map-note').textContent='Location unavailable or permission denied. Showing Delhi; move the map and search here.';toast('Allow location access to find hospitals near you.')},{timeout:12000})};map.on('moveend',()=>{clearTimeout(mapTimer);mapTimer=setTimeout(()=>{const c=map.getCenter();center=[c.lat,c.lng];findHospitals()},700)});findHospitals()}
async function findHospitals(){if(!$('#hospitals'))return;const generation=++searchGeneration;searchController?.abort();searchController=new AbortController();const timer=setTimeout(()=>searchController.abort(),25000);$('#hospitals').textContent='Finding hospitals…';const radius=Number($('#radius').value)*1000;const query=`[out:json][timeout:20];nwr["amenity"="hospital"](around:${radius},${center[0]},${center[1]});out center tags;`;try{const res=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:'data='+encodeURIComponent(query),headers:{'Content-Type':'application/x-www-form-urlencoded'},signal:searchController.signal});if(!res.ok)throw Error();const data=await res.json();if(generation!==searchGeneration||!$('#hospitals'))return;markers.clearLayers();const items=data.elements.map(e=>({...e,lat:e.lat??e.center.lat,lon:e.lon??e.center.lon})).sort((a,b)=>distance(a)-distance(b));$('#hospitals').innerHTML=items.length?'':'No hospitals found in this radius. Try a larger radius or move the map.';items.forEach(e=>{const name=e.tags.name||'Hospital',point=[e.lat,e.lon];const marker=L.marker(point).addTo(markers).bindPopup(esc(name));const row=document.createElement('div');row.className='hospital';row.innerHTML=`<strong>${esc(name)}</strong><p>${distance(e).toFixed(1)} km away${e.tags['addr:street']?' · '+esc(e.tags['addr:street']):''}</p><a target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${e.lat},${e.lon}">Get directions ↗</a>${e.tags.phone?` · <a href="tel:${esc(e.tags.phone.replace(/[^+0-9]/g,''))}">Call</a>`:''}`;const b=document.createElement('button');b.className='outline';b.textContent='Show on map';b.onclick=()=>{map.setView(point,15);marker.openPopup()};row.append(document.createElement('br'),b);$('#hospitals').append(row)})}catch(e){if(generation===searchGeneration&&$('#hospitals')){$('#hospitals').innerHTML='Hospital search is unavailable. <button class="outline" id="retry">Retry</button>';$('#retry').onclick=findHospitals}}finally{clearTimeout(timer)}}
function distance(e){const r=Math.PI/180,dl=(e.lat-center[0])*r,dn=(e.lon-center[1])*r,a=Math.sin(dl/2)**2+Math.cos(center[0]*r)*Math.cos(e.lat*r)*Math.sin(dn/2)**2;return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}
function voice(id){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)return toast('Voice input is unavailable in this browser. Please type your message.');const s=new Speech();s.lang='en-IN';s.onresult=e=>{$(id).value=e.results[0][0].transcript;$(id).dispatchEvent(new Event('input'))};s.onerror=()=>toast('Voice input failed. Check microphone permission.');s.start();toast('Listening…')}
let chatBusy=false;const welcome={role:'assistant',content:'How can I help you with your health today?',time:new Date().toISOString()};
function chatbot(){app.innerHTML=nav('chatbot')+`<main class="chat-container"><div class="heading-row"><div><h1>AI Health Assistant</h1><p class="subtitle">Get personalized health guidance</p></div><div><button class="outline" id="export-chat">♧ &nbsp; Export</button> <button class="outline" id="clear-chat">♜ &nbsp; Clear</button></div></div><section class="panel chat"><div class="chat-title"><span style="color:#27db65">♧</span> &nbsp; Chat with AI Assistant</div><div class="messages" id="messages" role="log" aria-live="polite"></div><form id="chat-form" class="composer"><div class="input-wrap"><input id="chat-input" aria-label="Message" placeholder="Ask me about your health..." required maxlength="8000"><button type="button" class="mic" id="voice-chat" aria-label="Voice input">♩</button></div><button class="green" id="send" aria-label="Send message">➤</button></form></section><p class="note">AI responses require a connected service in <a href="#/api">API settings</a>. Messages are saved on this browser. Sending shares your conversation with your configured service.</p></main>`;renderMessages();$('#voice-chat').onclick=()=>voice('#chat-input');$('#export-chat').onclick=()=>download('qure-chat.json',JSON.stringify(read('chat'),null,2));$('#clear-chat').onclick=()=>{save('chat',[]);renderMessages();toast('Chat cleared')};$('#chat-form').onsubmit=async e=>{e.preventDefault();if(chatBusy)return;const content=$('#chat-input').value.trim();if(!content)return;const config=read('config',{});if(!config.endpoint)return toast('Connect your AI service in API settings first.');const messages=read('chat');messages.push({role:'user',content,time:new Date().toISOString()});save('chat',messages);$('#chat-input').value='';renderMessages();chatBusy=true;$('#send').disabled=true;try{const text=await askAI(messages);const latest=read('chat');latest.push({role:'assistant',content:text,time:new Date().toISOString()});save('chat',latest);if($('#messages'))renderMessages()}catch(err){toast(err.message)}finally{chatBusy=false;if($('#send'))$('#send').disabled=false}}}
function renderMessages(){const messages=read('chat');$('#messages').innerHTML=(messages.length?messages:[welcome]).map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.content)}<span class="time">${new Date(m.time).toLocaleTimeString()}</span></div>`).join('');$('#messages').scrollTop=$('#messages').scrollHeight}
async function askAI(messages,system){const config=read('config',{});if(!config.endpoint)throw Error('Connect an AI service in API settings to continue.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);try{const res=await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'application/json',...(sessionStorage.getItem('qure-key')?{Authorization:'Bearer '+sessionStorage.getItem('qure-key')}:{})},body:JSON.stringify({model:config.model||'sarvam-m',messages:[{role:'system',content:system||'You are Qure, a health information assistant. Provide cautious, clear general information. Do not diagnose, prescribe, or claim certainty. For emergency symptoms advise immediate emergency help. Encourage appropriate professional care.'},...messages.map(({role,content})=>({role,content}))]}),signal:controller.signal});if(!res.ok)throw Error(`AI service returned ${res.status}. Check your API settings.`);const data=await res.json();const text=data.choices?.[0]?.message?.content||data.reply||data.response;if(typeof text!=='string'||!text.trim())throw Error('The service returned an unsupported response format.');return text}catch(e){if(e.name==='AbortError')throw Error('The AI service timed out. Please try again.');if(e instanceof TypeError)throw Error('Could not reach the AI service. Check its address and browser access settings.');throw e}finally{clearTimeout(timer)}}
const common=['Headache','Fever','Cough','Sore throat','Fatigue','Nausea','Chest pain','Shortness of breath','Dizziness','Back pain','Stomach pain','Joint pain'];let symptomTab='search';
function symptoms(){const h=read('symptoms'),week=Date.now()-7*86400000;app.innerHTML=nav('symptoms')+`<main class="container"><div class="heading-row"><div><h1>Symptom Intelligence</h1><p class="subtitle">AI-powered symptom analysis and medical guidance</p></div><button id="export-history" class="outline">♧ &nbsp;Export History</button></div><div class="stats">${[['Total Searches',h.length],['This Week',h.filter(x=>new Date(x.time).getTime()>=week).length],['Low Risk',h.filter(x=>x.risk==='low').length],['High Priority',h.filter(x=>x.risk==='high').length]].map(([t,n])=>`<div class="stat">${t}<strong>${n}</strong></div>`).join('')}</div><div class="tabs" role="tablist">${[['search','Symptom Search'],['history','Search History'],['emergency','Emergency Guide']].map(([r,t])=>`<button role="tab" aria-selected="${symptomTab===r}" data-tab="${r}" class="${symptomTab===r?'active':''}">${t}</button>`).join('')}</div><div id="symptom-content"></div></main>`;$('#export-history').onclick=()=>download('qure-symptom-history.json',JSON.stringify(h,null,2));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{symptomTab=b.dataset.tab;symptoms()});if(symptomTab==='search'){$('#symptom-content').innerHTML=`<section class="panel symptom-panel"><h3>Describe Your Symptoms</h3><form class="composer" id="symptom-form"><div class="input-wrap"><input id="symptom-input" placeholder="Enter your symptoms (e.g., headache, fever, cough)..." aria-label="Symptoms" required maxlength="4000"><button type="button" class="mic" id="voice-symptom" aria-label="Voice input">♩</button></div><button class="green" id="analyze">⌕ &nbsp; Analyze</button></form><p class="note">Common symptoms:</p><div class="chips">${common.map(t=>`<button data-symptom="${t}">${t}</button>`).join('')}</div></section><section class="panel results" id="results" aria-live="polite"><div style="font-size:55px;color:#d1d5db">⌕</div><h3>Ready to Help</h3><p>Enter your symptoms above or use voice search to get AI-powered analysis and recommendations.</p><p class="note">Requires a connected AI service. This tool provides information and cannot diagnose a condition.</p></section>`;$('#voice-symptom').onclick=()=>voice('#symptom-input');document.querySelectorAll('[data-symptom]').forEach(b=>b.onclick=()=>{const i=$('#symptom-input'),list=i.value.split(',').map(x=>x.trim()).filter(Boolean);if(!list.includes(b.dataset.symptom))list.push(b.dataset.symptom);i.value=list.join(', ')});$('#symptom-form').onsubmit=analyzeSymptoms}else if(symptomTab==='history'){$('#symptom-content').innerHTML=`<section class="panel"><div class="heading-row"><h3>Search History</h3><button class="outline" id="clear-history">Clear history</button></div>${h.length?h.slice().reverse().map(x=>`<article class="hospital"><strong>${esc(x.symptoms)}</strong><p>${new Date(x.time).toLocaleString()} · ${x.risk==='high'?'High priority':'AI information'}</p><p style="white-space:pre-wrap">${esc(x.answer)}</p></article>`).join(''):'<p>No searches yet.</p>'}</section>`;$('#clear-history').onclick=()=>{save('symptoms',[]);symptoms()}}else $('#symptom-content').innerHTML=`<section class="panel"><h3>Emergency Guide</h3><p>If you think someone may be in immediate danger, contact local emergency services now. Do not wait for this website or an AI response.</p><p>Examples include severe difficulty breathing, unconsciousness, severe bleeding, or sudden chest pain. An online tool cannot rule out an emergency.</p><a class="green" href="tel:112">Call 112 (India)</a><p class="note">Outside India, use your local emergency number.</p></section>`}
async function analyzeSymptoms(e){e.preventDefault();const input=$('#symptom-input').value.trim();if(!input)return;const emergency=/chest pain|shortness of breath|difficulty breathing|unconscious|severe bleeding/i.test(input);if(emergency){const answer='These symptoms may need urgent medical attention. If severe, sudden, or you feel in immediate danger, contact local emergency services now. Do not wait for an AI response.';const history=read('symptoms');history.push({symptoms:input,answer,risk:'high',time:new Date().toISOString()});save('symptoms',history);$('#results').innerHTML=`<h3>Seek urgent medical attention</h3><p>${answer}</p><a href="tel:112" class="green">Call 112 (India)</a>`;return}if(!read('config',{}).endpoint)return toast('Connect your AI service in API settings to analyze symptoms.');$('#analyze').disabled=true;$('#results').textContent='Analyzing symptoms…';try{const answer=await askAI([{role:'user',content:input}],'Provide cautious general information about the described symptoms, potential explanations without diagnosis or probability estimates, reasonable next steps, and when to seek urgent care. Do not prescribe. Clearly state that a clinician must assess the person.');const h=read('symptoms');h.push({symptoms:input,answer,risk:'unclassified',time:new Date().toISOString()});save('symptoms',h);if($('#results'))$('#results').innerHTML=`<h3>Symptom Information</h3><p style="white-space:pre-wrap;text-align:left">${esc(answer)}</p>`}catch(err){if($('#results'))$('#results').textContent=err.message}finally{if($('#analyze'))$('#analyze').disabled=false}}
function api(){const c=read('config',{});app.innerHTML=nav('api')+`<main class="container setting"><h1>API Configuration</h1><p class="subtitle">Connect your AI health assistant</p><form class="panel" id="api-form"><h3>AI Service Settings</h3><p>Use an OpenAI-compatible chat completion endpoint or your own backend proxy. The original site's AI configuration is unavailable.</p><label for="endpoint">Chat completions endpoint</label><input id="endpoint" type="url" required placeholder="https://your-service.example/chat/completions" value="${esc(c.endpoint||'')}"><label for="model">Model</label><input id="model" placeholder="sarvam-m" value="${esc(c.model||'sarvam-m')}"><label for="key">Bearer token (optional, this tab only)</label><input id="key" type="password" autocomplete="off" placeholder="Enter token if your endpoint requires one"><p class="note">For a public site, connect your own backend proxy that keeps provider credentials on the server. This browser sends requests directly to your endpoint, which must permit browser access. A bearer token entered here stays in session storage until this tab is closed or disconnected.</p><button class="green">Save Settings</button> <button class="outline" id="test-api" type="button">Test Connection</button> <button class="outline" type="button" id="disconnect">Disconnect</button><p id="api-status" role="status"></p></form><div class="panel" style="margin-top:24px"><h3>Your Data</h3><p>Chat and symptom history are stored in this browser. AI requests share the submitted conversation with your configured service. Maps use OpenStreetMap and Overpass. Cloud sync is not configured.</p><button class="outline" id="export-all">Export all data</button> <button class="outline" id="delete-all">Delete health history</button></div></main>`;$('#api-form').onsubmit=e=>{e.preventDefault();const url=new URL($('#endpoint').value);if(url.protocol!=='https:'&&url.hostname!=='localhost')return toast('Use an HTTPS endpoint.');save('config',{endpoint:url.href,model:$('#model').value.trim()});if($('#key').value)sessionStorage.setItem('qure-key',$('#key').value);$('#key').value='';toast('API settings saved')};$('#test-api').onclick=async()=>{$('#api-status').textContent='Testing saved connection…';try{await askAI([{role:'user',content:'Reply with OK.'}]);if($('#api-status'))$('#api-status').textContent='Connection successful.'}catch(e){if($('#api-status'))$('#api-status').textContent=e.message}};$('#disconnect').onclick=()=>{save('config',{});sessionStorage.removeItem('qure-key');api();toast('Disconnected')};$('#export-all').onclick=()=>download('qure-data.json',JSON.stringify({chat:read('chat'),symptoms:read('symptoms')},null,2));$('#delete-all').onclick=()=>{save('chat',[]);save('symptoms',[]);toast('Health history deleted')}}
function route(){const hash=location.hash;if(['#tools','#info','#about'].includes(hash)){if(!$('.hero'))home();requestAnimationFrame(()=>$(hash)?.scrollIntoView());return}clearTimeout(mapTimer);searchController?.abort();if(map){map.remove();map=null}const page=hash.replace('#/','')||'home';({home,medimap,chatbot,symptoms,api,settings:api,'api-portal':apiPortal}[page]||home)();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);route();

function apiPortal(){app.innerHTML=nav('api')+`<main class="container"><div style="text-align:center;max-width:1000px;margin:55px auto 65px"><h1>Qure Hospital API</h1><p class="subtitle">Integrate our AI-powered triage infrastructure directly into your hospital systems. Scale your patient processing, reduce practitioner burnout, and prioritize critical cases with our enterprise-grade API.</p></div><div class="cards">${[['search','Symptom Intelligence','Evaluate symptoms, determine urgency levels, and generate detailed reasoning reports explaining assessments before a patient reaches a doctor.'],['pin','Pre-arrival Patient Data','Receive patient information transmitted via MediMap before arrival. Reduce intake time and accelerate emergency treatment seamlessly.'],['database','QIS Integration','Securely access combined health data from wearable devices (heart rate, blood oxygen, ECG) to build a unified patient profile prior to consultation.']].map(([i,t,d])=>`<article class="card">${icon(i)}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div><section class="panel" style="text-align:center;margin:50px 0;padding:50px"><h2 style="font-size:36px">Ready to upgrade your infrastructure?</h2><p>Subscribe to Qure Hospital to access our AI triage and integration services. Built for scale, security, and healthcare compliance. Final medical decisions always remain with your qualified professionals.</p><a class="green" href="#/settings">Get API Keys</a> <button class="outline" id="read-docs">Read Documentation</button><p class="note">Recreated portal: hospital subscriptions, QIS, and patient transmission services are not connected. Connect an existing AI provider in settings.</p><div id="api-docs"></div></section></main>`;$('#read-docs').onclick=()=>{$('#api-docs').innerHTML='<div class="panel" style="text-align:left;margin-top:25px"><h3>Integration Documentation</h3><p>Configure an existing AI service under <a href="#/settings">AI service settings</a>. Use a server-side proxy for your provider credentials. Accept POST JSON containing model and messages; return choices[0].message.content. This recreation does not issue hospital API keys or transmit patient records.</p></div>'}}

